<script module lang="ts">
/**
 * A styled native table, the main data display in ListPage (`design/components/table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import {
  agentMember,
  joinSlot,
  pressTableSort,
  tableSort,
  tableSortColumns,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/table.module.css'
import type { TableCellProps } from './TableCell.svelte'
import type { TableHeaderProps } from './TableHeader.svelte'
import type { TableRowProps } from './TableRow.svelte'

export type CellProps = TableCellProps

export type HeaderProps = TableHeaderProps

export type RowProps = TableRowProps

export type SortDirection = 'asc' | 'desc'

export interface TableProps {
  /**
   * Names the **table** with a real `<caption>`, its first child. `label` names the *scroll
   * region*, which exists only while the columns overflow, so a table that fits has no name.
   * That is fine for a page's main table, but a dashboard's chart twin tables would be announced
   * as "table, table, table". Announced but not drawn unless `captionVisible`, because most
   * tables already have their name on screen: a page title, or the chart they are the twin of.
   */
  caption?: string
  /**
   * Draws the caption above the table as well as announcing it, for a table whose name is not
   * already beside it. Not left to composition as Heading's caption is, because a `Text` above
   * the table would not be connected to it, and `<caption>` is the element for a table's name.
   */
  captionVisible?: boolean
  children?: Snippet
  /**
   * The table is a **grid**: one tab stop, arrow keys between cells, and rows that may carry
   * `aria-selected`. Only for a component that owns every cell, in practice DataTable. A
   * hand-composed table is a document of prose and links, browsed with the reader's own keys,
   * and taking the arrow keys for a focus ring would only cost them.
   */
  grid?: boolean
  /**
   * Names the scroll region for keyboard users, usually the page's title.
   */
  label?: string
  /**
   * Rows can be selected in bulk. Only meaningful inside a grid, where it tells a screen reader
   * whether "selected" means one of many or the only one.
   */
  multiselectable?: boolean
  stickyHeader?: boolean
}
</script>

<script lang="ts">
let {
  caption,
  captionVisible = false,
  children,
  grid = false,
  label: labelOwn,
  multiselectable = false,
  stickyHeader = false,
}: TableProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let overflowing = $state(false)
let at = $state({ row: 0, column: 0, detail: false })
let placed = $state(false)
let holds = $state(false)
let table = $state<HTMLElement | null>(null)
let wrapper = $state<HTMLElement | null>(null)
const stopIn = $derived((cell: HTMLTableCellElement): HTMLElement => {
  for (const node of Array.from(
    cell.querySelectorAll<HTMLElement>('button, a[href], input, select, textarea'),
  )) {
    if (node.hasAttribute('disabled') || node.getAttribute('aria-hidden') === 'true') continue
    return node
  }
  return cell
})
const gridRows = $derived((element: HTMLTableElement): HTMLTableRowElement[] =>
  Array.from(element.rows).filter((row) => !row.hasAttribute('data-detail')),
)
const detailUnder = $derived(
  (row: HTMLTableRowElement | undefined): HTMLTableCellElement | null => {
    const next = row?.nextElementSibling
    return next instanceof HTMLTableRowElement && next.hasAttribute('data-detail')
      ? (next.cells[0] ?? null)
      : null
  },
)
const gridCellOf = $derived(
  (element: HTMLTableElement, target: EventTarget | null): HTMLTableCellElement | null => {
    let cell = target instanceof HTMLElement ? target.closest<HTMLTableCellElement>('th, td') : null
    while (cell !== null && cell.closest('table') !== element) {
      cell = cell.parentElement?.closest<HTMLTableCellElement>('th, td') ?? null
    }
    if (cell === null || cell.parentElement === null) return null
    return cell.parentElement.hasAttribute('data-detail') && cell !== target ? null : cell
  },
)
const positionOf = $derived(
  (
    element: HTMLTableElement,
    cell: HTMLTableCellElement,
    column: number,
  ): { row: number; column: number; detail: boolean } => {
    const row = cell.parentElement as HTMLTableRowElement
    const rows = gridRows(element)
    return row.hasAttribute('data-detail')
      ? {
          row: rows.indexOf(row.previousElementSibling as HTMLTableRowElement),
          column,
          detail: true,
        }
      : { row: rows.indexOf(row), column: cell.cellIndex, detail: false }
  },
)
const clampCell = $derived(
  (
    element: HTMLTableElement,
    to: { row: number; column: number; detail: boolean },
  ): { row: number; column: number; detail: boolean } | null => {
    const rows = gridRows(element)
    const row = Math.min(Math.max(to.row, 0), rows.length - 1)
    const cells = rows[row]?.cells
    if (cells === undefined || cells.length === 0) return null
    return {
      row,
      column: Math.min(Math.max(to.column, 0), cells.length - 1),
      detail: to.detail && row === to.row && detailUnder(rows[row]) !== null,
    }
  },
)
const startOf = $derived(
  (element: HTMLTableElement): { row: number; column: number; detail: boolean } => {
    const cells = Array.from(gridRows(element)[0]?.cells ?? [])
    const column = cells.findIndex((cell) => cell.querySelector('[data-undrawn]') === null)
    return { row: 0, column: Math.max(column, 0), detail: false }
  },
)
const whereIn = $derived(
  (element: HTMLTableElement): { row: number; column: number; detail: boolean } =>
    placed ? at : startOf(element),
)
const stopAt = $derived(
  (
    element: HTMLTableElement,
    to: { row: number; column: number; detail: boolean },
  ): HTMLElement | null => {
    const row = gridRows(element)[to.row]
    if (to.detail) return detailUnder(row)
    const cell = row?.cells[to.column]
    return cell === undefined ? null : stopIn(cell)
  },
)
const rove = $derived(
  (element: HTMLTableElement, to: { row: number; column: number; detail: boolean }) => {
    at = to
    for (const [index, row] of gridRows(element).entries()) {
      for (const cell of Array.from(row.cells)) {
        const stop = stopIn(cell)
        const wanted = !to.detail && index === to.row && cell.cellIndex === to.column ? '0' : '-1'
        if (stop !== cell && cell.getAttribute('tabindex') !== '-1')
          cell.setAttribute('tabindex', '-1')
        if (stop.getAttribute('tabindex') !== wanted) stop.setAttribute('tabindex', wanted)
      }
      const under = detailUnder(row)
      const held = to.detail && index === to.row ? '0' : '-1'
      if (under !== null && under.getAttribute('tabindex') !== held)
        under.setAttribute('tabindex', held)
    }
  },
)
const focusIn = $derived((event: FocusEvent) => {
  const element = table as HTMLTableElement | null
  if (element === null) return
  if (!holds) holds = true
  const cell = gridCellOf(element, event.target)
  if (cell === null) return
  const to = clampCell(element, positionOf(element, cell, whereIn(element).column))
  if (to === null) return
  placed = true
  rove(element, to)
})
const focusOut = $derived((event: FocusEvent) => {
  const element = table as HTMLTableElement | null
  const left = event.target
  queueMicrotask(() => {
    if (
      element !== null &&
      left instanceof Node &&
      left.isConnected &&
      !element.contains(document.activeElement)
    )
      holds = false
  })
})
const keyDown = $derived((event: KeyboardEvent) => {
  const element = table as HTMLTableElement | null
  const target = event.target instanceof HTMLElement ? event.target : null
  if (
    element === null ||
    target === null ||
    target.closest(
      'input:not([type="checkbox"]):not([type="radio"]), textarea, [contenteditable]',
    ) !== null
  )
    return
  const cell = gridCellOf(element, target)
  if (cell === null) return
  const rows = gridRows(element)
  const here = positionOf(element, cell, whereIn(element).column)
  const forward = getComputedStyle(element).direction === 'rtl' ? -1 : 1
  const far = event.ctrlKey || event.metaKey
  const last = Number.MAX_SAFE_INTEGER
  let next: { row: number; column: number; detail: boolean } | null
  if (here.detail) {
    switch (event.key) {
      case 'ArrowDown':
        next = here.row + 1 < rows.length ? { ...here, row: here.row + 1, detail: false } : null
        break
      case 'ArrowUp':
        next = { ...here, detail: false }
        break
      case 'ArrowRight':
      case 'ArrowLeft':
        next = null
        break
      case 'Home':
        next = far ? { row: 0, column: 0, detail: false } : null
        break
      case 'End':
        next = far ? { row: last, column: last, detail: false } : null
        break
      default:
        return
    }
  } else {
    switch (event.key) {
      case 'ArrowRight':
        next = { ...here, column: here.column + forward }
        break
      case 'ArrowLeft':
        next = { ...here, column: here.column - forward }
        break
      case 'ArrowDown':
        next =
          detailUnder(rows[here.row]) !== null
            ? { ...here, detail: true }
            : { ...here, row: here.row + 1 }
        break
      case 'ArrowUp':
        next =
          detailUnder(rows[here.row - 1]) !== null
            ? { ...here, row: here.row - 1, detail: true }
            : { ...here, row: here.row - 1 }
        break
      case 'Home':
        next = far ? { row: 0, column: 0, detail: false } : { ...here, column: 0 }
        break
      case 'End':
        next = far ? { row: last, column: last, detail: false } : { ...here, column: last }
        break
      default:
        return
    }
  }
  event.preventDefault()
  const to = next === null ? null : clampCell(element, next)
  if (to === null) return
  placed = true
  rove(element, to)
  stopAt(element, to)?.focus()
})
const reclamp = $derived(() => {
  const element = table as HTMLTableElement | null
  if (element === null || !grid) return
  const to = clampCell(element, whereIn(element))
  if (to === null) return
  rove(element, to)
  const fell = document.activeElement === null || document.activeElement === document.body
  if (holds && fell) stopAt(element, to)?.focus()
})
setContext('polymorph:Table', {
  get grid() {
    return grid
  },
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    overflowing = wrapper !== null && wrapper.scrollWidth > wrapper.clientWidth
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [wrapper, wrapper?.firstElementChild]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    reclamp()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [table])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled'],
      })
  release2 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect2, { watch: () => grid })
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran =
    wrapper?.parentElement?.closest('[data-member]')?.getAttribute('data-member') === 'data-table'
      ? () => {}
      : agentMember({
          member: 'Table',
          element: () => wrapper,
          state: () => ({
            'sort-key': tableSort(table).key,
            'sort-direction': tableSort(table).direction,
            columns: tableSortColumns(table),
          }),
          actions: { sort: { argument: 'id', run: (value) => pressTableSort(table, value) } },
        })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={wrapper}
    class={styles.wrapper}
    data-sticky-header={(stickyHeader) ? '' : undefined}
    data-overflowing={(overflowing) ? '' : undefined}
    tabindex={(overflowing && !grid ? '0' : undefined) as never}
    role={overflowing && label !== undefined ? 'region' : undefined}
    aria-label={overflowing ? label : undefined}
    data-member="table"
    ><table
      bind:this={table}
      class={styles.table}
      role={grid ? 'grid' : undefined}
      aria-multiselectable={grid && multiselectable ? 'true' : undefined}
      onfocusin={(event) => { if (grid) focusIn(event) }}
      onfocusout={(event) => { if (grid) focusOut(event) }}
      onkeydown={(event) => { if (grid) keyDown(event) }}
      >{#if caption !== undefined
        }<caption
          class={[captionVisible ? styles.caption : undefined, !captionVisible ? styles.captionHidden : undefined]}
          >{caption
        }</caption
      >{/if
      }{@render children?.()
    }</table
  ></div
>{/if
}{@render joined.end?.()}
